Definition find_rangeIF (ri : rindex) (e : expr) : option (Z * Z) := find_rangeF (ri_bucket ri (vkey_of e)) e.
Lemma find_rangeIF_eq : forall ri e, find_rangeIF ri e = find_rangeI ri e.
Proof.
