Fixpoint esz (e : expr) : nat :=
  match e with
  | EAlu _ a b | EAluw _ a b | EMd _ a b | EMdw _ a b => S (esz a + esz b)
  | EExt _ _ _ a => S (esz a)
  | _ => 1%nat
  end.
