Definition hask (e : expr) : bool := match e with EAlu ALU_ADD _ (ELit _) => true | _ => false end.
Lemma split_lit_shape : forall e B k, split_lit e = (B, k) -> is_lit B = None ->
  (hask e = true /\ e = EAlu ALU_ADD B (ELit k)) \/ (hask e = false /\ e = B /\ k = 0).
Proof.
